        { id: 'n3', ownerOnly: true, when: { favorMin: 45 },
          reason: '茶终于没再凉',
          reward: { address: '阿茶', phrase: '茶凉过三回了。',
                    pose: '把那只一直温着的杯推过来，指尖在杯沿停很久' },
          text: '雨歇了，她把那只一直温着的杯推到陛下手里，自己却没另取一只。「往后，陛下便唤臣妾阿茶罢。」说罢耳根先红，忙拿广袖去掩，指尖却在杯沿上停了很久。案上灯芯积了长长一截，谁也没去剪。' }
